import (
	"fmt"
)

resp, err := client.Email().SendEmail(ctx, map[string]any{
	"recipients":  []any{"customer@example.com"},
	"cc":          []any{"orders@example.com"},
	"subject":     "Your order has shipped",
	"htmlContent": "<p>Your order is on its way.</p>",
	"contentType": "text/html",
}, "", nil)
if err != nil {
	log.Fatal(err)
}
body := resp.Map().(map[string]any)
fmt.Println(body["status"], body["accepted"], body["cc"])
